//	def compute_proposer_index(state: BeaconState, indices: Sequence[ValidatorIndex], seed: Bytes32) -> ValidatorIndex:
//	   """
//	   Return from ``indices`` a random index sampled by effective balance.
//	   """
//	   assert len(indices) > 0
