			randomValue := uint64(randomBytes[offset]) | uint64(randomBytes[offset+1])<<8

			if effectiveBal*fieldparams.MaxRandomValueElectra >= beaconConfig.MaxEffectiveBalanceElectra*randomValue {
				return candidateIndex, nil
